mapper.select:
SELECT F.FUNDACCT, IBF_GET_PARAMNAME('SYSTEM','INVTP',C.INVTP) INVTP_NAME, C.INVTP, C.INVNM, IBF_GET_PARAMNAME('SYSTEM','IDTP',C.IDTP) IDTP_NAME, C.IDTP, C.IDNO, IBF_GET_PARAMNAME('SYSTEM','FDACST',F.FDACST) FDACST_NAME, F.FDACST, C.OPENDT, IBF_GET_PARAMNAME('SYSTEM','CUSTTP',E.CUSTTP) CUSTTP_NAME, E.CUSTTP, T.TRADEACCO, ECC_IBF_GET_BANK_NAME(T.BANKNO) BANKNAME, T.BANKNO, T.BANKACCO, R.TRADEFLAG AS TRADEACCOST, IBF_GET_PARAMNAME('SYSTEM','MELONMD',T.MELONMD) MELONMD_NAME, T.MELONMD, T.NETPOINT FROM TRADEACCOINFO T, FUNDACCOINFO F, TRADEACCORELA R, CUSTINFO C, CUSTINFOEX E WHERE R.CUSTNO = T.CUSTNO AND R.TRADEACCO = T.TRADEACCO AND R.CUSTNO = F.CUSTNO(+) AND R.FUNDACCT = F.FUNDACCT(+) AND R.TANO = F.TANO(+) AND R.CUSTNO = C.CUSTNO AND R.CUSTNO = E.CUSTNO
AND TRIM(F.FUNDACCT) = #{sp.fundacct}
AND C.IDNO = #{sp.idno}
AND C.INVNM LIKE '%'||#{sp.invnm}||'%'
AND C.CUSTST = #{sp.custst}
AND T.REGIONCODE = #{sp.qway}
AND T.NETPOINT = #{sp.netpoint}
ORDER BY C.INVNM,C.OPENDT ASC

SELECT COUNT(*) FROM TRADEACCOINFO T, FUNDACCOINFO F, TRADEACCORELA R, CUSTINFO C, CUSTINFOEX E WHERE R.CUSTNO = T.CUSTNO AND R.TRADEACCO = T.TRADEACCO AND R.CUSTNO = F.CUSTNO(+) AND R.FUNDACCT = F.FUNDACCT(+) AND R.TANO = F.TANO(+) AND R.CUSTNO = C.CUSTNO AND R.CUSTNO = E.CUSTNO
AND TRIM(F.FUNDACCT) = #{sp.fundacct}
AND C.IDNO = #{sp.idno}
AND C.INVNM LIKE '%'||#{sp.invnm}||'%'
AND C.CUSTST = #{sp.custst}
AND T.REGIONCODE = #{sp.qway}
AND T.NETPOINT = #{sp.netpoint}
ORDER BY C.INVNM,C.OPENDT ASC

SELECT F.FUNDACCT, IBF_GET_PARAMNAME('SYSTEM','INVTP',C.INVTP) INVTP_NAME, C.INVTP, C.INVNM, IBF_GET_PARAMNAME('SYSTEM','IDTP',C.IDTP) IDTP_NAME, C.IDTP, C.IDNO, IBF_GET_PARAMNAME('SYSTEM','FDACST',F.FDACST) FDACST_NAME, F.FDACST, C.OPENDT, IBF_GET_PARAMNAME('SYSTEM','CUSTTP',E.CUSTTP) CUSTTP_NAME, E.CUSTTP, T.TRADEACCO, ECC_IBF_GET_BANK_NAME(T.BANKNO) BANKNAME, T.BANKNO, T.BANKACCO, (CASE WHEN R.TRADEFLAG = 'Y' THEN '正常' WHEN R.TRADEFLAG = 'N' THEN '无效' END) TRADEACCOST_NAME, R.TRADEFLAG AS TRADEACCOST, IBF_GET_PARAMNAME('SYSTEM','MELONMD',T.MELONMD) MELONMD_NAME, T.MELONMD, T.NETPOINT FROM TRADEACCOINFO T, FUNDACCOINFO F, TRADEACCORELA R, CUSTINFO C, CUSTINFOEX E WHERE R.CUSTNO = T.CUSTNO AND R.TRADEACCO = T.TRADEACCO AND R.CUSTNO = F.CUSTNO(+) AND R.FUNDACCT = F.FUNDACCT(+) AND R.TANO = F.TANO(+) AND R.CUSTNO = C.CUSTNO AND R.CUSTNO = E.CUSTNO
AND TRIM(F.FUNDACCT) = #{sp.fundacct}
AND C.IDNO = #{sp.idno}
AND C.INVNM LIKE '%'||#{sp.invnm}||'%'
AND C.CUSTST = #{sp.custst}
AND T.REGIONCODE = #{sp.qway}
AND T.NETPOINT = #{sp.netpoint}
ORDER BY C.INVNM,C.OPENDT ASC

SELECT I.FUNDID, I.FUNDNM, I.NAV, E.FACEVALUE, I.NAVDT FROM FUNDINFO I, FUNDINFOEX E WHERE I.FUNDID = E.FUNDID
AND I.NAVDT >= #{sp.startDate}
AND I.NAVDT <= #{sp.endDate}
ORDER BY I.FUNDNM ASC, NAVDT DESC, I.FUNDID ASC

SELECT COUNT(*) FROM FUNDINFO I, FUNDINFOEX E WHERE I.FUNDID = E.FUNDID
AND I.NAVDT >= #{sp.startDate}
AND I.NAVDT <= #{sp.endDate}
ORDER BY I.FUNDNM ASC, NAVDT DESC, I.FUNDID ASC

SELECT B.FUNDACCT, C.INVNM, E.CUSTTP, B.TRADEACCO, T.BANKNO, T.BANKACCO, T.BANKACNM, B.FUNDID, F.FUNDNM, B.BALANCE, TRUNC(B.BALANCE - NVL(QN.CHANGEQUTY,0) - NVL(QY.CHANGEQUTY,0) - B.ABNMFROZEN, 2) AS AVAILABLE, TRUNC(NVL(QN.CHANGEQUTY,0),2) AS FROZEN, TRUNC(NVL(QY.CHANGEQUTY,0),2) AS HFROZEN, B.ABNMFROZEN, F.NAV, T.NETPOINT FROM FUNDBALANCE B, CUSTINFO C, CUSTINFOEX E, TRADEACCOINFO T, FUNDINFO F, (SELECT TRADEACCO, FUNDID, SHARETYPE, SUM(CHANGEQUTY) AS CHANGEQUTY FROM TRADEREQUEST_QTRACE WHERE TRANSST = 'N' GROUP BY TRADEACCO, FUNDID, SHARETYPE) QN, (SELECT TRADEACCO, FUNDID, SHARETYPE, SUM(CHANGEQUTY) AS CHANGEQUTY FROM TRADEREQUEST_QTRACE WHERE TRANSST = 'Y' GROUP BY TRADEACCO, FUNDID, SHARETYPE) QY WHERE B.CUSTNO = C.CUSTNO AND B.CUSTNO = E.CUSTNO AND B.TRADEACCO = T.TRADEACCO AND B.FUNDID = F.FUNDID AND B.TRADEACCO = QN.TRADEACCO(+) AND B.FUNDID = QN.FUNDID(+) AND B.SHARETYPE = QN.SHARETYPE(+) AND B.TRADEACCO = QY.TRADEACCO(+) AND B.FUNDID = QY.FUNDID(+) AND B.SHARETYPE = QY.SHARETYPE(+)
AND TRIM(B.FUNDACCT) = #{sp.fundacct}
AND F.TANO = #{sp.tano}
AND C.INVNM LIKE '%'||#{sp.invnm}||'%'
AND T.REGIONCODE = #{sp.qway}
AND T.NETPOINT = #{sp.netpoint}

SELECT COUNT(*) FROM FUNDBALANCE B, CUSTINFO C, CUSTINFOEX E, TRADEACCOINFO T, FUNDINFO F, (SELECT TRADEACCO, FUNDID, SHARETYPE, SUM(CHANGEQUTY) AS CHANGEQUTY FROM TRADEREQUEST_QTRACE WHERE TRANSST = 'N' GROUP BY TRADEACCO, FUNDID, SHARETYPE) QN, (SELECT TRADEACCO, FUNDID, SHARETYPE, SUM(CHANGEQUTY) AS CHANGEQUTY FROM TRADEREQUEST_QTRACE WHERE TRANSST = 'Y' GROUP BY TRADEACCO, FUNDID, SHARETYPE) QY WHERE B.CUSTNO = C.CUSTNO AND B.CUSTNO = E.CUSTNO AND B.TRADEACCO = T.TRADEACCO AND B.FUNDID = F.FUNDID AND B.TRADEACCO = QN.TRADEACCO(+) AND B.FUNDID = QN.FUNDID(+) AND B.SHARETYPE = QN.SHARETYPE(+) AND B.TRADEACCO = QY.TRADEACCO(+) AND B.FUNDID = QY.FUNDID(+) AND B.SHARETYPE = QY.SHARETYPE(+)
AND TRIM(B.FUNDACCT) = #{sp.fundacct}
AND F.TANO = #{sp.tano}
AND C.INVNM LIKE '%'||#{sp.invnm}||'%'
AND T.REGIONCODE = #{sp.qway}
AND T.NETPOINT = #{sp.netpoint}
ORDER BY C.INVNM ASC

SELECT B.FUNDACCT, C.INVNM, E.CUSTTP, B.TRADEACCO, T.BANKNO, T.BANKACCO, T.BANKACNM, B.FUNDID, F.FUNDNM, B.BALANCE, TRUNC(B.BALANCE - NVL(QN.CHANGEQUTY,0) - NVL(QY.CHANGEQUTY,0) - B.ABNMFROZEN, 2) AS AVAILABLE, TRUNC(NVL(QN.CHANGEQUTY,0),2) AS FROZEN, TRUNC(NVL(QY.CHANGEQUTY,0),2) AS HFROZEN, B.ABNMFROZEN, F.NAV, T.NETPOINT FROM FUNDBALANCE B, CUSTINFO C, CUSTINFOEX E, TRADEACCOINFO T, FUNDINFO F, (SELECT TRADEACCO, FUNDID, SHARETYPE, SUM(CHANGEQUTY) AS CHANGEQUTY FROM TRADEREQUEST_QTRACE WHERE TRANSST = 'N' GROUP BY TRADEACCO, FUNDID, SHARETYPE) QN, (SELECT TRADEACCO, FUNDID, SHARETYPE, SUM(CHANGEQUTY) AS CHANGEQUTY FROM TRADEREQUEST_QTRACE WHERE TRANSST = 'Y' GROUP BY TRADEACCO, FUNDID, SHARETYPE) QY WHERE B.CUSTNO = C.CUSTNO AND B.CUSTNO = E.CUSTNO AND B.TRADEACCO = T.TRADEACCO AND B.FUNDID = F.FUNDID AND B.TRADEACCO = QN.TRADEACCO(+) AND B.FUNDID = QN.FUNDID(+) AND B.SHARETYPE = QN.SHARETYPE(+) AND B.TRADEACCO = QY.TRADEACCO(+) AND B.FUNDID = QY.FUNDID(+) AND B.SHARETYPE = QY.SHARETYPE(+)
AND TRIM(B.FUNDACCT) = #{sp.fundacct}
AND F.TANO = #{sp.tano}
AND C.INVNM LIKE '%'||#{sp.invnm}||'%'
AND T.REGIONCODE = #{sp.qway}
AND T.NETPOINT = #{sp.netpoint}
ORDER BY C.INVNM ASC
